package service
import("testing";"time";"ballast-watch/internal/model";"ballast-watch/internal/store")
func TestBug30_DeduplicatesSameSecond(t *testing.T){svc:=ballastTestServices(t);v:=mustVessel(t,svc);tank:=mustTank(t,svc,v);p:=mustPointBallast(t,svc,tank);at:=time.Date(2026,1,1,8,0,0,0,time.FixedZone("CST",8*3600));_,err:=svc.WaterReadings.Ingest(ballastCtx(),&model.WaterWaterReadingTreatmentCycle{WaterReadings:[]model.WaterWaterReadingInput{{SamplingPointID:p.ID,ParamType:model.ParamHumidity,Value:40,MeasuredAt:at.Format(time.RFC3339Nano)},{SamplingPointID:p.ID,ParamType:model.ParamHumidity,Value:41,MeasuredAt:at.Format(time.RFC3339Nano)}}});if err!=nil{t.Fatal(err)};rows,err:=svc.WaterReadings.Query(ballastCtx(),store.WaterReadingQuery{SamplingPointID:p.ID,ParamType:model.ParamHumidity,Limit:10});if err!=nil{t.Fatal(err)};if len(rows)!=1{t.Fatalf("duplicate readings stored: %d",len(rows))}}
